import {categories,categoryById} from './catalog.js';
import {standings} from './series.js';
export function createSeriesUI({esc,photo,cover}){
 const options=selected=>categories.map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${esc(c.name)}</option>`).join('');
 const points=n=>n>1?Array.from({length:n},(_,i)=>n-i).join(' · '):'Oyuncu sayısına göre';
 function preview(plan,settings){const ids=plan.mode==='playlist'?plan.playlist:[settings.categoryId];return `<div class="plan-preview"><span class="eyebrow">${plan.mode==='playlist'?'Bu akşamın listesi':plan.mode==='vote'?'Oylamalı seri':'Tek tur'}</span>${plan.mode==='vote'?`<p>${plan.rounds} tur · İlk kategori: <strong>${esc(categoryById(settings.categoryId)?.name)}</strong></p><p class="fine">Sonraki turları masadakiler seçer.</p>`:ids.map((id,i)=>`<div class="plan-item">${photo(cover(categoryById(id)),'plan-photo')}<span class="plan-number">${i+1}</span><strong>${esc(categoryById(id).name)}</strong></div>`).join('')}</div>`;}
 function config(plan,settings,n,pick){return `<section class="series-setup"><div class="section-label"><h3>Akşamın akışı</h3><span class="pill">${plan.mode==='playlist'?plan.playlist.length:plan.mode==='vote'?plan.rounds:1} tur</span></div><div class="series-modes" role="group" aria-label="Seri oynama şekli">${[['playlist','Oyun listesi','Kategorileri ekle, sırayla oynayın.'],['vote','Oylamalı seri','Her turda sıradaki oyunu seçin.'],['single','Tek tur','Bir kategoriyle hızlı bir maç.']].map(([id,title,description])=>`<button type="button" data-plan-mode="${id}" class="series-mode ${plan.mode===id?'selected':''} ${id==='single'?'compact':''}" aria-pressed="${plan.mode===id}"><strong>${title}</strong><small>${description}</small></button>`).join('')}</div>${plan.mode==='playlist'?`<div class="playlist-builder"><label for="playlist-category">Listeye kategori ekle</label><div class="playlist-add"><select name="playlist-category" id="playlist-category">${options(pick)}</select><button class="btn secondary" type="button" data-action="playlist-add" ${plan.playlist.length>=10?'disabled':''}>Ekle ＋</button></div><div class="playlist-items">${plan.playlist.length?plan.playlist.map((id,i)=>`<div class="playlist-item">${photo(cover(categoryById(id)),'plan-photo')}<span class="plan-number">${i+1}</span><strong>${esc(categoryById(id).name)}</strong><div class="playlist-controls"><button type="button" data-list-op="up" data-index="${i}" aria-label="${i+1}. turu yukarı taşı" ${i===0?'disabled':''}>↑</button><button type="button" data-list-op="down" data-index="${i}" aria-label="${i+1}. turu aşağı taşı" ${i===plan.playlist.length-1?'disabled':''}>↓</button><button type="button" data-list-op="remove" data-index="${i}" aria-label="${i+1}. turu listeden çıkar">×</button></div></div>`).join(''):'<p class="empty-list">İlk kategorini ekle. En fazla 10 tur oynayabilirsiniz.</p>'}</div></div>`:`${plan.mode==='vote'?`<div><label for="series-rounds">Kaç tur oynayalım?</label><select name="seriesRounds" id="series-rounds">${Array.from({length:10},(_,i)=>i+1).map(v=>`<option value="${v}" ${plan.rounds===v?'selected':''}>${v} tur</option>`).join('')}</select></div>`:''}<div><label for="first-category">${plan.mode==='vote'?'İlk tur kategorisi':'Kategori'}</label><select name="categoryId" id="first-category">${options(settings.categoryId)}</select></div>`}${plan.mode!=='single'?`<p class="series-rule">Her turda sıralamana göre seri puanı alırsın: <strong>${n>1?points(n):'Birinci en yüksek puanı alır'}</strong>. Her yeni turda bütçe ve kadrolar sıfırlanır.</p>`:''}</section>`;}
 function board(s,heading='Genel sıralama'){return `<section class="series-board panel"><div class="section-label"><h2>${heading}</h2><span class="pill">${s.results.length}/${s.totalRounds} tur</span></div><div class="standing-list">${standings(s).map(p=>`<div class="standing ${p.rank===1&&s.results.length?'first':''}"><span class="standing-rank">${p.rank}.</span><span class="avatar">${esc(p.name[0])}</span><strong>${esc(p.name)}</strong><span class="standing-points">${p.total}<small>puan</small></span></div>`).join('')}</div><p class="fine">Seri puanları: ${points(s.players.length)}. Eşit sırayı paylaşanlar aynı puanı alır.</p></section>`;}
 function progress(s){return `<div class="series-progress"><span>${s.mode==='playlist'?'Oyun listesi':'Oylamalı seri'}</span><strong>Tur ${s.vote?.round||s.round} / ${s.totalRounds}</strong><span>${s.results.length} tur puanlandı</span></div>`;}
 function roundControls(s,host,draft){const result=s.results.find(r=>r.round===s.round);return `<section class="round-judging panel">${s.phase==='review'?`<span class="eyebrow">Tur ${s.round} · Sıralama bekleniyor</span><h2>${host?'Bu tur kim önde?':'Sıralama birazdan belli.'}</h2><p class="muted">Kadroları tartışın veya ChatGPT promptuyla karşılaştırın. ${host?'Sonra her oyuncunun sırasını seç.':'Oda sahibi sonucu kaydedince seri puanları eklenecek.'}</p>${host?`<form id="round-ranking"><div class="rank-fields">${s.players.map(p=>`<label>${esc(p.name)}<select name="rank:${p.id}" aria-label="${esc(p.name)} sırası" required><option value="">Sıra seç</option>${s.players.map((_,i)=>`<option value="${i+1}" ${draft[p.id]===i+1?'selected':''}>${i+1}. · ${s.players.length-i} puan</option>`).join('')}</select></label>`).join('')}</div><p class="fine">${s.players.length===2?'Beraberlik için ikisine de 1. sırayı seçebilirsin.':'Beraberlik olabilir: 1, 1, 3 gibi. Sonraki sırayı atlayın.'}</p><button class="btn lime wide" type="submit">Tur sıralamasını kaydet</button></form>`:''}`:`<span class="eyebrow">Tur ${s.round} · Puanlar eklendi</span><h2>Bu turun sıralaması</h2><div class="round-places">${[...result.placements].sort((a,b)=>a.rank-b.rank).map(p=>`<div><span>${p.rank}. ${esc(p.name)}</span><strong>+${p.points} puan</strong></div>`).join('')}</div>${s.phase==='between'?host?`<button class="btn lime wide" data-action="series-next">${s.mode==='vote'?'Kategori oylamasını aç':'Listedeki sonraki tura geç'} →</button>`:'<p class="waiting-note">Oda sahibi sıradaki turu açacak.</p>':''}`}</section>${board(s)}`;}
 function vote(s,you,local,voter){const v=s.vote,selected=v.votes[local?voter:you],cast=Object.keys(v.votes).length;return `${progress(s)}<section class="vote-heading"><span class="eyebrow">${v.round}. turu birlikte seçin</span><h1>Sırada ne oynuyoruz?</h1><p class="muted">Üç seçenek, bir sonraki oyun. İlk oyla 10 saniye başlar; herkes oy verince kalan süre en fazla 3 saniye olur.</p>${local?`<div class="local-voters" role="group" aria-label="Oy veren oyuncu">${s.players.map(p=>`<button data-voter="${p.id}" class="${voter===p.id?'selected':''}" aria-pressed="${voter===p.id}">${esc(p.name)}${v.votes[p.id]?' · Oy verdi':''}</button>`).join('')}</div>`:''}<div class="vote-status"><span>${cast}/${s.players.length} kişi oy verdi</span><strong data-vote-timer>${v.deadline?'':'İlk oy bekleniyor'}</strong></div></section><div class="vote-options">${v.candidates.map(id=>{const c=categoryById(id),votes=Object.values(v.votes).filter(choice=>choice===id).length;return `<button class="vote-option ${selected===id?'chosen':''}" data-vote-category="${id}" aria-pressed="${selected===id}">${photo(cover(c),'vote-photo',true)}<span class="vote-caption"><strong>${esc(c.name)}</strong><small>${votes} oy${selected===id?' · Senin seçimin':''}</small></span></button>`;}).join('')}</div><p class="fine">Süre bitene kadar oyunu değiştirebilirsin. Eşitlikte en çok oy alan kategoriler arasından rastgele seçim yapılır.</p>${board(s)}`;}
 function final(s,host){const ranked=standings(s),winners=ranked.filter(p=>p.rank===1);return `<section class="series-final-banner result-banner"><span class="eyebrow">${s.totalRounds} tur · Seri finali</span><h1>${winners.length===1?esc(winners[0].name)+' seriyi kazandı.':'Zirve paylaşıldı.'}</h1><p>${winners.map(p=>esc(p.name)).join(', ')} · ${winners[0].total} seri puanı</p><div class="result-actions">${host?'<button class="btn lime" data-action="rematch">Yeni seri kur</button>':''}<button class="btn secondary" data-action="copy-series-prompt">Seri için ChatGPT promptu</button><button class="btn ghost" data-action="copy-series">Tüm sonuçları kopyala</button><button class="btn ghost" data-action="home">Kategorilere dön</button></div></section>${board(s,'Akşamın sıralaması')}<section class="series-recap"><h2>Tur tur sonuçlar</h2>${s.results.map(r=>`<details class="round-recap"><summary><span>${r.round}. ${esc(categoryById(r.categoryId).name)}</span><small>Kadroları gör ＋</small></summary><div class="recap-players">${[...r.placements].sort((a,b)=>a.rank-b.rank).map(p=>`<article><h3>${p.rank}. ${esc(p.name)} <span>+${p.points} puan</span></h3>${r.game.players.find(player=>player.id===p.id).cards.map(card=>`<div class="recap-card">${photo(card,'roster-photo')}<span>${esc(card.name)}</span><small>${card.paid} jeton</small></div>`).join('')}</article>`).join('')}</div></details>`).join('')}</section>`;}
 return {config,preview,board,progress,roundControls,vote,final};
}
